"""Pins the per-event causal numbers the engine produces since A4 (python -m tests.fixtures.parity.make_a4_golden).

A4 changes the causal model on purpose (no ad-driven covariates, controls screened, temporal Lasso folds), so these
numbers no longer equal the frozen prototype's. This golden is generated by the ENGINE, not by the prototype: it
detects regressions from here on, it is not evidence of parity. The script prints how far each event moved from the
prototype's snapshot, which is what the A10 calibration starts from.

    uv run python -m tests.fixtures.parity.make_a4_golden            # synthetic (versioned: snapshot_a4_events.json)
    uv run python -m tests.fixtures.parity.make_a4_golden --real     # Gol (git-ignored: real/gol_a4_events.json)

Regenerate only with approval, after reading the printed deltas.
"""

import argparse
import json
import tempfile
from pathlib import Path

from threadpoolctl import threadpool_limits

from engine.config import EngineConfig
from engine.pipeline import compute
from tests.engine.real_data import GOL_CONFIG, GOL_LEGACY, engine_snapshot, gol_files
from tests.engine.synthetic_data import dataset_config, make_dataset

HERE = Path(__file__).resolve().parent
SYNTHETIC_GOLDEN = HERE / "snapshot_a4_events.json"
GOL_GOLDEN = HERE / "real" / "gol_a4_events.json"
SYNTHETIC_LEGACY = HERE / "snapshot.json"


def events_block(computed) -> list[dict]:
    return engine_snapshot(computed)["events"]


def _numbers(node, prefix=""):
    if isinstance(node, dict):
        for key, value in node.items():
            yield from _numbers(value, f"{prefix}.{key}")
    elif isinstance(node, (int, float)) and not isinstance(node, bool):
        yield prefix, float(node)


def describe_deltas(new_events: list[dict], legacy_events: list[dict]) -> list[str]:
    legacy = {e["event_id"]: e for e in legacy_events}
    lines = []
    for event in new_events:
        old = legacy.get(event["event_id"])
        if old is None:
            lines.append(f"{event['event_id']}: not in the prototype snapshot")
            continue
        flags = [f"{k} {old[k]} -> {event[k]}" for k in ("passed", "reasons", "selected") if old[k] != event[k]]
        old_numbers = dict(_numbers(old["results_data"] or {}))
        worst = 0.0
        for key, value in _numbers(event["results_data"] or {}):
            if key in old_numbers and old_numbers[key] != 0:
                worst = max(worst, abs(value - old_numbers[key]) / abs(old_numbers[key]))
        controls = (event["results_data"] or {}).get("controls_rejected")
        lines.append(
            f"{event['event_id']}: max relative change {worst:.3g}"
            + (f"; {'; '.join(flags)}" if flags else "")
            + (f"; controls rejected: {controls}" if controls else "")
        )
    return lines


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--real", action="store_true", help="Gol (needs exemplo_csv/ and real/gol.json)")
    args = parser.parse_args()
    if args.real:
        with threadpool_limits(limits=1):
            computed = compute(gol_files(), EngineConfig.from_input(GOL_CONFIG))
        target, legacy_path = GOL_GOLDEN, GOL_LEGACY
    else:
        with tempfile.TemporaryDirectory() as tmp:
            computed = compute(make_dataset(Path(tmp)), EngineConfig.from_input(dataset_config()))
        target, legacy_path = SYNTHETIC_GOLDEN, SYNTHETIC_LEGACY
    events = events_block(computed)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(events, indent=1), encoding="utf-8")
    legacy_events = json.loads(legacy_path.read_text(encoding="utf-8"))["events"]
    print(f"wrote {target}")
    print("\n".join(describe_deltas(events, legacy_events)))


if __name__ == "__main__":
    main()
